const bump=(u,a,b)=>u<=a||u>=b?0:Math.sin(Math.PI*(u-a)/(b-a));
// ---------- forms ----------
const CRE=DATA.creatures.map(prepCreature);
let FORMS=CRE[0].forms;
function prepCreature(c){const n=c.pal.length;const o={name:c.name,biome:c.biome,fx:c.fx,white:c.roles.white,outline:c.roles.outline};
  o.pal32=c.pal.map(h=>h?hex2u32(h):0);o.HOTTER=[...Array(n).keys()];o.COOLER=[...Array(n).keys()];
  c.roles.hotter.forEach(([a,b])=>o.HOTTER[a]=b);c.roles.cooler.forEach(([a,b])=>o.COOLER[a]=b);
  o.hot=new Set(c.roles.hot);o.mass=new Set(c.roles.mass);o.cool=new Set();
  for(let i=1;i<n;i++)if(!o.hot.has(i)&&!o.mass.has(i)&&i!==o.outline&&i!==o.white)o.cool.add(i);
  o.forms=c.forms.map(f=>prepForm(f,o));return o}
function setCreature(i){CUR=CRE[i];PAL=CUR.pal32;HOTTER=CUR.HOTTER;COOLER=CUR.COOLER;FX=CUR.fx;FORMS=CUR.forms}
function prepForm(F,CR){
  const w=F.w,h=F.h,n=w*h,r=F.rig;
  const idx=Uint8Array.from(atob(F.b64),c=>c.charCodeAt(0));
  const kind=new Uint8Array(n),dist=new Float32Array(n).fill(-1),zid=new Uint8Array(n),zw=new Float32Array(n);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){
    const c=idx[y*w+x];if(!c)continue;
    if(CR.hot.has(c)){
      let crack=false;
      for(let dy=-2;dy<=2&&!crack;dy++)for(let dx=-2;dx<=2;dx++){const xx=x+dx,yy=y+dy;if(xx<0||yy<0||xx>=w||yy>=h)continue;if(CR.cool.has(idx[yy*w+xx])){crack=true;break}}
      kind[y*w+x]=crack?1:2;
    }else if(CR.mass.has(c))kind[y*w+x]=2;
  }
  if(r.calm)for(const[x0,y0,x1,y1]of r.calm)for(let y=Math.max(0,y0);y<Math.min(h,y1);y++)for(let x=Math.max(0,x0);x<Math.min(w,x1);x++){const i=y*w+x;if(CR.hot.has(idx[i]))kind[i]=0}
  // geodesic distance from the core through hot pixels
  let best=-1,bd=1e9;const[cx0,cy0]=r.core;
  for(let i=0;i<n;i++)if(kind[i]){const d=(i%w-cx0)**2+((i/w|0)-cy0)**2;if(d<bd){bd=d;best=i}}
  const q=new Int32Array(n);let qh=0,qt=0;if(best>=0){dist[best]=0;q[qt++]=best}
  while(qh<qt){const i=q[qh++],x=i%w,y=i/w|0,d=dist[i];
    for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;const xx=x+dx,yy=y+dy;if(xx<0||yy<0||xx>=w||yy>=h)continue;const j=yy*w+xx;if(!kind[j]||dist[j]>=0)continue;dist[j]=d+(dx&&dy?1.41:1);q[qt++]=j}}
  for(let i=0;i<n;i++)if(dist[i]<0)dist[i]=Math.hypot(i%w-cx0,(i/w|0)-cy0)*1.2;
  r.zones.forEach((z,k)=>{const[zx,zy,zr,za]=z;for(let y=Math.max(0,zy-zr|0);y<Math.min(h,zy+zr+1);y++)for(let x=Math.max(0,zx-zr|0);x<Math.min(w,zx+zr+1);x++){const d=Math.hypot(x-zx,y-zy)/zr;if(d>=1)continue;const f=(1-d*d)*za,i=y*w+x;if(f>zw[i]){zw[i]=f;zid[i]=k}}});
  // foot span for shadow
  let fx0=w,fx1=0;for(let y=Math.max(0,r.feet-5);y<=Math.min(h-1,r.feet+1);y++)for(let x=0;x<w;x++)if(idx[y*w+x]){fx0=Math.min(fx0,x);fx1=Math.max(fx1,x)}
  return{w,h,idx,kind,dist,zid,zw,rig:r,fx0,fx1,name:r.name,tw:new Float32Array(n)};
}
// ---------- background ----------
const bgBuf=new Uint32Array(SW*SH);const SH0=224,GYV=205;
const anim={fall:[],lake:[],crack:[],glow:[],vein:[]};
function genBG(){
  const B=new Uint32Array(SW*SH0),occ=new Uint8Array(SW*SH),fgm=new Uint8Array(SW*SH);let mark=0;
  const put=(x,y,c)=>{if(x>=0&&y>=0&&x<SW&&y<SH0){B[y*SW+x]=c;if(mark)occ[y*SW+x]=1;if(mark===2)fgm[y*SW+x]=1}};
  const pick=(v,x,y,ramp)=>{const k=v*(ramp.length-1);const i=Math.floor(k),f=k-i;return ramp[clamp(i+(f>bay(x,y)?1:0),0,ramp.length-1)]};
  // wall
  const wall=[C.b0,C.b1,C.b2,C.b3,C.b4];
  for(let y=0;y<SH0;y++)for(let x=0;x<SW;x++){
    let v=.12+.55*clamp(y/150,0,1)+.28*(n2(x/16,y/10)-.5)+.12*(n2(x/5,y/4)-.5);
    let c=pick(clamp(v,0,1),x,y,wall);
    const warm=Math.exp(-(((y-152)/22)**2));
    if(warm>.2&&bay(x,y)<warm*.85)c=warm>.75?C.g3:warm>.45?C.g2:C.g1;
    B[y*SW+x]=c;
  }
  // faint lava veins in the back wall
  for(let v=0;v<5;v++){let x=64+R()*128,y=30+R()*30;const L=20+R()*28;let dx=R()-.5;for(let i=0;i<L;i++){anim.vein.push(Math.round(y)*SW+Math.round(x),Math.round(x),Math.round(y),i/L);x+=dx*1.2+(R()-.5)*.9;y+=.55+R()*.5;dx+=(R()-.5)*.3;dx=clamp(dx,-.8,.8);if(R()<.06){const bx=x,by=y;for(let j=0;j<6;j++)anim.vein.push(Math.round(by+j*.6)*SW+Math.round(bx+j*(R()<.5?-1:1)),Math.round(bx+j),Math.round(by+j*.6),.9)}}}
  // far ridge
  for(let x=0;x<SW;x++){const r=Math.round(110+16*n1(x/30,3)+7*n1(x/9,4));
    for(let y=r;y<156;y++){let c=C.b2;if(y===r)c=C.b5;else if(y===r+1)c=C.b4;else if(y<r+4&&bay(x,y)<.5)c=C.b3;else if(n2(x/6,y/5)>.68)c=C.b3;
      const warm=clamp((y-132)/22,0,1);if(bay(x,y)<warm*.7)c=warm>.6?C.g2:C.g1;put(x,y,c)}}
  // basalt cliffs: two rows of hexagonal columns on each side, stepping down toward the centre
  mark=0;
  const colTop=new Int16Array(SW).fill(999);
  const col=(x0,wid,top,row)=>{const dark=row===0;if(row===0)for(let x=x0;x<x0+wid;x++)colTop[x]=top;let j=top+5+Math.floor(hsh(x0,top)*8);
    const body=dark?C.b2:C.b3,lit=dark?C.b3:C.b5,lit2=dark?C.b4:C.b6,cap=dark?C.b4:C.b7;
    for(let y=top;y<158;y++){for(let x=x0;x<x0+wid;x++){let c=body;const lx=x-x0;
      if(lx===0)c=lit;else if(lx===1&&!dark)c=C.b4;else if(lx===wid-1)c=C.b1;
      if(hsh(x*3,y*7)<.07)c=dark?C.b1:C.b2;
      if(y===top){c=(lx>0&&lx<wid-1)?cap:lit2}else if(y===top+1){c=lx<wid/2?cap:lit2;if(lx===wid-1)c=lit}else if(y===top+2){c=lx===wid-1?C.b1:lit}
      if(y===j){c=C.b1}else if(y===j+1&&lx>0&&lx<wid-1)c=lit;
      const warm=clamp((y-132)/24,0,1)*(row?.9:.55);if(y>top+2&&lx>0&&lx<wid-1&&bay(x,y)<warm*.7)c=warm>.7?C.g3:C.g2;
      put(x,y,c)}
      if(y===j)j+=8+Math.floor(hsh(x0,y)*10)}};
  const cliff=(xa,xb,dir,row)=>{let x=xa;while(x<xb){const wid=5+Math.floor(R()*4);const k=dir>0?(x-xa)/(xb-xa):(xb-x)/(xb-xa);
    const top=Math.round((row?92:70)+k*(row?52:44)+R()*12-(R()<.18?14:0));col(x,wid,top,row);x+=wid}};
  cliff(0,52,1,0);cliff(198,256,-1,0);cliff(0,40,1,1);cliff(212,256,-1,1);
  mark=0;
  // lava cascade out of a fissure in the left cliff
  const fx=46,fy=Math.max(...[44,45,46,47,48].map(x=>colTop[x]))+7;
  for(let y=fy-4;y<=fy+3;y++)for(let x=fx-4;x<=fx+4;x++){const d=Math.hypot((x-fx)/4,(y-fy)/3);if(d<1)put(x,y,d<.5?C.L1:C.b1)}
  for(let y=fy;y<156;y++){const cx=fx+1+Math.sin(y*.09)*.8+(y-fy)*.06,hw=1.8+(y-fy)*.06;
    for(let x=Math.floor(cx-hw-1);x<=Math.ceil(cx+hw+1);x++){const e=Math.abs(x-cx)/hw;if(e>1.3)continue;anim.fall.push(y*SW+x,x,y,e)}}
  // lava lake
  for(let y=150;y<178;y++)for(let x=0;x<SW;x++)anim.lake.push(y*SW+x,x,y);
  // ceiling + stalactites
  mark=1;
  const ceil=x=>Math.round(14+9*n1(x/24,7)+5*n1(x/7,8));
  for(let x=0;x<SW;x++){const c0=ceil(x);for(let y=0;y<=c0;y++){let c=bay(x,y)<.5?C.b0:C.b1;if(y===c0)c=C.g1;else if(y===c0-1)c=C.b2;put(x,y,c)}}
  for(let k=0;k<22;k++){const x0=Math.floor(R()*SW),wv=5+Math.floor(R()*8),L=10+Math.floor(R()*24),c0=ceil(x0);
    for(let y=c0;y<c0+L;y++){const hw=wv/2*Math.pow(1-(y-c0)/L,1.15);for(let x=Math.round(x0-hw);x<=Math.round(x0+hw);x++){let c=C.b2;if(x===Math.round(x0-hw))c=C.b4;else if(x===Math.round(x0+hw))c=C.b1;if(y>=c0+L-3)c=y===c0+L-1?C.g3:C.g2;put(x,y,c)}}}
  // platform (basalt column tops, voronoi)
  mark=1;
  const seeds=[];for(let j=0;j<9;j++){const y=176+j*j*.55+j*3;for(let i=-1;i<15;i++){seeds.push([i*19+(j%2)*9+R()*7,y+R()*2.5])}}
  const top=x=>Math.round(178+2*n1(x/14,11));
  for(let y=170;y<SH0;y++)for(let x=0;x<SW;x++){
    if(y<top(x))continue;
    let d1=1e9,d2=1e9,s1=null;
    for(const s of seeds){const dx=(x-s[0]),dy=(y-s[1])*2.2;const d=dx*dx+dy*dy;if(d<d1){d2=d1;d1=d;s1=s}else if(d<d2)d2=d}
    const edge=Math.sqrt(d2)-Math.sqrt(d1);
    let c;
    if(y>=214){c=(y===214)?C.b4:C.b2;if(edge<1.4)c=C.b1;if(y>218&&bay(x,y)<.5)c=C.b1}
    else{c=C.b3;const ly=(y-s1[1]);if(ly<-1)c=C.b4;if(ly<-2.5&&(x-s1[0])<0)c=C.b5;if(ly>1.5)c=C.b2;if(edge<1.3)c=C.b1;if(y===top(x))c=C.b6;
      const dc=Math.hypot((x-CX)/1,(y-GYV)*3.2);
      if(edge<1.2&&dc<120&&hsh(Math.round(s1[0]),Math.round(s1[1]))<.72){anim.crack.push(y*SW+x,x,y,dc);}
      const gd=Math.hypot((x-CX)/76,(y-GYV+1)/13);if(gd<1)anim.glow.push(y*SW+x,x,y,gd,c);
    }
    B[y*SW+x]=c;occ[y*SW+x]=1;
  }
  // foreground rocks
  mark=2;
  const rock=(cx,cy,rx,ry)=>{for(let y=cy-ry;y<SH0;y++)for(let x=cx-rx;x<=cx+rx;x++){const d=((x-cx)/rx)**2+((y-cy)/ry)**2+(n2(x/6,y/4)-.5)*.6;if(d<1){let c=bay(x,y)<.6?C.b0:C.b1;const up=(cy-y)/ry;if(up>.25&&d>.55&&bay(x,y)<(d-.4))c=up>.6?C.g3:C.g2;if(up>.5&&d>.85)c=C.g4;put(x,y,c)}}};
  rock(10,222,30,14);rock(250,220,26,16);rock(36,226,18,8);
  mark=0;
  const filt=(arr,stride,m)=>{const o=[];for(let k=0;k<arr.length;k+=stride)if(!m[arr[k]])for(let j=0;j<stride;j++)o.push(arr[k+j]);return o};
  anim.lake=filt(anim.lake,3,occ);anim.vein=filt(anim.vein,4,occ);anim.fall=filt(anim.fall,4,occ);anim.glow=filt(anim.glow,5,fgm);anim.crack=filt(anim.crack,4,fgm);
  // compose into the taller canvas: extra rock rows on top, everything else shifted down by YO
  for(let y=0;y<YO;y++)for(let x=0;x<SW;x++)bgBuf[y*SW+x]=bay(x,y)<.5?C.b0:C.b1;
  bgBuf.set(B,YO*SW);
  const sh=(arr,stride)=>{for(let k=0;k<arr.length;k+=stride){arr[k]+=YO*SW;arr[k+2]+=YO}};
  sh(anim.fall,4);sh(anim.lake,3);sh(anim.glow,5);sh(anim.crack,4);sh(anim.vein,4);
}
genBG();

// ---------- sky biome (Ruban) ----------
const SKYH={s0:'05041a',s1:'0a0830',s2:'120d48',s3:'1d1560',s4:'2a1d78',s5:'3c2a92',s6:'52399f',n1:'34186a',n2:'521f80',n3:'1d3a74',st1:'fffbe0',st2:'c9c3ff',st3:'7d76d0',m1:'fff3c4',m2:'f0d890',m3:'c9a860',m4:'8a7448',k0:'0c0a2c',k1:'161044',k2:'2a2264',k3:'463a8c',c1:'221a5a',c2:'302676',c3:'443596',c4:'6150b6',c5:'8a7ad8',c6:'b9adf0',c7:'e8e2ff',g1:'f4b20c'};
const K2={};for(const k in SKYH)K2[k]=hex2u32(SKYH[k]);
const skyBuf=new Uint32Array(SW*SH),skyStars=[],skyLights=[];
function genSky(){const B=skyBuf,put=(x,y,c)=>{if(x>=0&&y>=0&&x<SW&&y<SH)B[y*SW+x]=c};
  const ramp=[K2.s0,K2.s1,K2.s2,K2.s3,K2.s4,K2.s5,K2.s6];const Rs=mulberry(77);
  for(let y=0;y<SH;y++)for(let x=0;x<SW;x++){
    const v=clamp(y/190,0,1)*.95+.08*(n2(x/20,y/14)-.5);const k=clamp(v,0,1)*(ramp.length-1),i=Math.floor(k);let c=ramp[clamp(i+((k-i)>bay(x,y)?1:0),0,ramp.length-1)];
    const yc=26+x*.38+14*n1(x/34,3),d=Math.abs(y-yc)/34;
    if(d<1){const ne=(1-d)*(.55+.6*(n2(x/16,y/10)-.5)+.3*(n2(x/6,y/5)-.5));if(ne>.32&&bay(x,y)<(ne-.3)*1.6)c=n2(x/40+5,y/30)>.55?K2.n3:(ne>.6?K2.n2:K2.n1)}
    B[y*SW+x]=c}
  const mx=210,my=44,mr=14;
  for(let y=my-36;y<=my+36;y++)for(let x=mx-36;x<=mx+36;x++){const d=Math.hypot(x-mx,y-my);
    if(d<=mr){const lx=(x-mx)/mr,ly=(y-my)/mr;let c=K2.m1;const sh=lx*.7+ly*.5;if(sh>.35)c=K2.m2;if(sh>.7)c=K2.m3;
      for(const[cx,cy,cr]of[[-5,-3,3],[4,4,2.5],[2,-6,2],[-2,7,2]])if(Math.hypot(x-mx-cx,y-my-cy)<cr)c=sh>.3?K2.m4:K2.m3;put(x,y,c)}
    else if(d<mr+22){const g=1-(d-mr)/22;if(bay(x,y)<g*.5)put(x,y,g>.6?K2.s6:K2.s5)}}
  for(let i=0;i<170;i++){const x=Math.floor(Rs()*SW),y=Math.floor(Rs()*172);if(Math.hypot(x-mx,y-my)<mr+8)continue;const q=Rs();skyStars.push([x,y,q<.06?2:q<.3?1:0,Rs()*6.28,.6+Rs()*2.2])}
  const peak=(cx,top,base,wk,lit)=>{for(let y=top;y<base;y++){const hw=(y-top)*wk+1+1.5*(n1(y/6,cx)-.5);const xa=Math.round(cx-hw),xb=Math.round(cx+hw);
    for(let x=xa;x<=xb;x++){let c=K2.k0;if(x===xb)c=lit?K2.k3:K2.k1;else if(x===xb-1)c=K2.k2;else if(x===xa)c=K2.k1;if(n2(x/3,y/4)>.74)c=K2.k1;put(x,y,c)}}};
  peak(30,112,206,.42,1);peak(58,140,206,.5,1);peak(226,104,206,.36,1);peak(248,132,206,.5,0);peak(152,162,206,.6,1);
  const px0=30,py0=112,tier=(y,hw)=>{for(let x=px0-hw;x<=px0+hw;x++)put(x,y,K2.k0);put(px0-hw-1,y-1,K2.k0);put(px0+hw+1,y-1,K2.k0)};
  for(let y=py0-14;y<py0;y++)for(let x=px0-2;x<=px0+2;x++)put(x,y,K2.k0);
  tier(py0-3,5);tier(py0-7,4);tier(py0-11,3);put(px0,py0-15,K2.k0);put(px0,py0-16,K2.k0);
  skyLights.push([px0-1,py0-5],[px0+1,py0-9],[px0+2,py0-2]);
}
genSky();
function cloudLayer(T,camx,camy,yb,amp,per,spd,ph,cf,cm,cr,hi){
  for(let x=0;x<SW;x++){const X=x+T*spd+ph;const w1=Math.pow(Math.abs(Math.sin(X/per*Math.PI)),.55),w2=Math.pow(Math.abs(Math.sin(X/(per*1.73)*Math.PI+1.3)),.6);
    const top=yb-amp*(.62*w1+.38*w2)-4*n1(X/19,ph|0)-2*n1(X/7,(ph|0)+3);const inner=top+5+amp*.5*(1-w1)+2*n1(X/11,9);
    for(let y=Math.ceil(top);y<SH;y++){const dy=y-top;let c=cf;if(dy<1.6)c=hi&&dy<.8?hi:cr;else if(dy<4.5&&bay(Math.floor(X),y)<.6)c=cm;else if(Math.abs(y-inner)<1&&w2>.5&&bay(Math.floor(X),y)<.5)c=cm;
      const X2=x+camx,Y2=y+camy;if(X2>=0&&Y2>=0&&X2<SW&&Y2<SH)buf[Y2*SW+X2]=c}}}
function drawSky(T,camx,camy){copyBG(skyBuf,camx,camy);
  for(const s of skyStars){const b=.5+.5*Math.sin(T*s[4]+s[3]),X=s[0]+camx,Y=s[1]+camy;
    if(s[2]===2){px(X,Y,K2.st1);if(b>.35){px(X-1,Y,K2.st2);px(X+1,Y,K2.st2);px(X,Y-1,K2.st2);px(X,Y+1,K2.st2)}}
    else if(s[2]===1)px(X,Y,b>.5?K2.st1:K2.st2);else if(b>.35)px(X,Y,b>.75?K2.st2:K2.st3)}
  skyLights.forEach(([x,y],i)=>px(x+camx,y+camy,Math.sin(T*4.3+i*2)>-.4?K2.g1:K2.m3));
  cloudLayer(T,camx,camy,180,7,22,2,0,K2.c1,K2.c2,K2.c3);
  cloudLayer(T,camx,camy,197,9,30,4.5,40,K2.c2,K2.c3,K2.c4);
  cloudLayer(T,camx,camy,214,10,38,7,90,K2.c3,K2.c4,K2.c5)}
function drawSkyFront(T,camx,camy){cloudLayer(T,camx,camy,235,11,46,11,17,K2.c4,K2.c5,K2.c6,K2.c7)}
function spawnShoot(){P.push({k:'sh',x:rnd(60,270),y:rnd(-6,64),vx:-rnd(110,170),vy:rnd(35,70),life:0,max:rnd(.5,.9)})}
function drawRays(F,K,u){const[px0,py0]=F.rig.pearl;const[cx,cy]=fwd(F,px0,py0,K);const L=18+46*u;
  for(let i=0;i<10;i++){const a=i/10*Math.PI*2+u*.9;for(let d=4;d<L;d++){const X=Math.round(cx+Math.cos(a)*d),Y=Math.round(cy+Math.sin(a)*d);if(bay(X,Y)<(1-u)*(1-d/L)*1.5)px(X,Y,PAL[d<L*.35?FX.ring[0]:FX.ring[1]])}}}

// ---------- ice biome (Givre) ----------
const ICEH={i0:'050a1f',i1:'0a1534',i2:'10214a',i3:'163063',i4:'1f4380',i5:'2b5c9e',i6:'3f7cc0',i7:'62a4dc',i8:'9fd2f0',i9:'e6f6ff',g1:'0f3a5a',g2:'17607e',g3:'22a0b8',g4:'5ef0f0',a1:'39f29b',a2:'2ad8e0',a3:'b35cf0',k0:'03051a',k1:'080d2c',st:'dfe8ff'};
const K3={};for(const k in ICEH)K3[k]=hex2u32(ICEH[k]);
const iceBuf=new Uint32Array(SW*SH),ice={hole:[],crys:[],crack:[],glow:[],tips:[],glint:[]};
function genIce(){const B=iceBuf,Ri=mulberry(911),occ=new Uint8Array(SW*SH);let mark=0;
  const put=(x,y,c)=>{x=Math.round(x);y=Math.round(y);if(x>=0&&y>=0&&x<SW&&y<SH){B[y*SW+x]=c;if(mark)occ[y*SW+x]=mark}};
  const wall=[K3.i0,K3.i1,K3.i2,K3.i3,K3.i4];
  const seeds=[];for(let i=0;i<46;i++)seeds.push([Ri()*SW,Ri()*190,Ri()]);
  for(let y=0;y<SH;y++)for(let x=0;x<SW;x++){let d1=1e9,d2=1e9,s1=null;for(const q of seeds){const d=(x-q[0])**2+((y-q[1])*1.3)**2;if(d<d1){d2=d1;d1=d;s1=q}else if(d<d2)d2=d}
    const edge=Math.sqrt(d2)-Math.sqrt(d1);let v=.12+.5*clamp(y/175,0,1)+.22*(s1[2]-.5)+.1*(n2(x/9,y/7)-.5);
    const k=clamp(v,0,1)*(wall.length-1),i=Math.floor(k);let c=wall[clamp(i+((k-i)>bay(x,y)?1:0),0,4)];
    if(edge<1.1&&y<172)c=v>.45?K3.i5:K3.i3;
    const mist=Math.exp(-(((y-164)/12)**2));if(mist>.25&&bay(x,y)<mist*.55)c=mist>.7?K3.i6:K3.i5;
    B[y*SW+x]=c}
  // opening in the ceiling with the night sky
  const hx=150,hy=18,hr=54;const holeAt=(x,y)=>{const a=Math.atan2(y-hy,x-hx);const r=hr*(1+.12*Math.sin(a*5+1)+.08*Math.sin(a*9))*(y<hy?1.6:1);return Math.hypot(x-hx,(y-hy)*2.1)<r};
  for(let y=0;y<60;y++)for(let x=0;x<SW;x++)if(holeAt(x,y)){const c=bay(x,y)<y/60?K3.k1:K3.k0;B[y*SW+x]=c;ice.hole.push(y*SW+x,x,y);if(Ri()<.025)B[y*SW+x]=K3.st}
  for(let y=0;y<62;y++)for(let x=0;x<SW;x++){if(holeAt(x,y))continue;const nb=holeAt(x,y-1)||holeAt(x,y-2);if(nb){B[y*SW+x]=holeAt(x,y-1)?K3.i8:K3.i6}}
  // ceiling icicles (with drip tips)
  const ceil=x=>Math.round(10+8*n1(x/20,4)+4*n1(x/6,5));
  for(let x=0;x<SW;x++){if(holeAt(x,ceil(x)))continue;for(let y=0;y<=ceil(x);y++)if(!holeAt(x,y))put(x,y,bay(x,y)<.5?K3.i0:K3.i1);put(x,ceil(x),K3.i4)}
  mark=1;
  const icicle=(x0,y0,wv,L)=>{for(let y=y0;y<y0+L;y++){const hw=wv/2*Math.pow(1-(y-y0)/L,1.1);const xa=Math.round(x0-hw),xb=Math.round(x0+hw);for(let x=xa;x<=xb;x++){let c=K3.i6;if(x===xa)c=K3.i8;else if(x===xb)c=K3.i4;else if(x===xa+1)c=K3.i7;if(y>=y0+L-2)c=K3.i9;put(x,y,c)}}ice.tips.push([x0,y0+L])};
  for(let k=0;k<34;k++){const x0=Math.floor(Ri()*SW);let y0=ceil(x0);if(holeAt(x0,y0+2)){let y=y0;while(y<62&&holeAt(x0,y))y++;if(y>=62)continue;y0=y}icicle(x0,y0,3+Math.floor(Ri()*5),6+Math.floor(Ri()*24))}
  // glowing ice crystals
  const crystal=(bx,by,h,w,tilt)=>{for(let t=0;t<h;t++){const y=by-t,cx=bx+tilt*t;const tipLen=w*1.1;const hw=t<h-tipLen?w/2:(h-t)/tipLen*w/2;const xa=Math.round(cx-hw),xb=Math.round(cx+hw);
      for(let x=xa;x<=xb;x++){const f=(x-cx)/Math.max(hw,.5);let c=f<-.35?K3.i7:f<.3?K3.i6:K3.i5,face=f<-.35?2:f<.3?1:0;if(x===xa){c=K3.i8;face=3}else if(x===xb)c=K3.i4;if(Math.abs(x-cx)<.6&&t%2===0){c=K3.g4;face=4}
        put(x,y,c);ice.crys.push(y*SW+x,x,y,t,face)}}
    for(let y=by-h-6;y<by+2;y++)for(let x=bx-w-8;x<=bx+w+8+tilt*h;x++){const i=y*SW+x;if(x<0||y<0||x>=SW||y>=SH||occ[i])continue;const d=Math.hypot((x-bx-tilt*(by-y))/(w+6),(y-(by-h/2))/(h/2+6));if(d<1&&bay(x,y)<(1-d)*.6)B[i]=d<.5?K3.g2:K3.g1}};
  [[14,182,70,9,.05],[30,180,48,7,-.12],[4,178,40,6,.2],[44,178,30,5,.18],[58,176,20,4,-.1],[236,182,78,10,-.06],[220,180,52,7,.14],[250,178,40,6,-.2],[206,178,28,5,-.15],[96,170,22,4,.1],[170,170,26,5,-.08]].forEach(a=>crystal(...a));
  // frozen floor (ice tiles) with snow drifts
  const tiles=[];for(let j=0;j<9;j++){const y=176+j*j*.55+j*3;for(let i=-1;i<15;i++)tiles.push([i*19+(j%2)*9+Ri()*7,y+Ri()*2.5])}
  const top=x=>Math.round(177+2*n1(x/14,21));
  for(let y=170;y<SH;y++)for(let x=0;x<SW;x++){if(y<top(x))continue;let d1=1e9,d2=1e9,s1=null;
    for(const q of tiles){const d=(x-q[0])**2+((y-q[1])*2.2)**2;if(d<d1){d2=d1;d1=d;s1=q}else if(d<d2)d2=d}
    const edge=Math.sqrt(d2)-Math.sqrt(d1);let c=K3.i3;const ly=y-s1[1];if(ly<-1)c=K3.i4;if(ly<-2.5&&(x-s1[0])<0)c=K3.i5;if(ly>1.5)c=K3.i2;if(edge<1.3)c=K3.i1;
    if(((x+y*2)%23)<2&&ly<0&&edge>2)c=K3.i6;
    const drift=y-top(x)<3+3*n1(x/9,30)||y>=232-4*n1(x/13,31);if(drift){c=bay(x,y)<.7?K3.i8:K3.i7;if(y===top(x))c=K3.i9;if(Ri()<.01)ice.glint.push(y*SW+x,x,y)}
    if(!drift&&edge<1.2){const dc=Math.hypot(x-CX,(y-GY)*3.2);if(dc<120&&hsh(Math.round(s1[0]),Math.round(s1[1]))<.72)ice.crack.push(y*SW+x,x,y,dc)}
    const gd=Math.hypot((x-CX)/76,(y-GY+1)/13);if(gd<1&&!drift)ice.glow.push(y*SW+x,x,y,gd);
    B[y*SW+x]=c}
  // snow mounds in the front corners
  const mound=(cx,cy,rx,ry)=>{for(let y=cy-ry;y<SH;y++)for(let x=cx-rx;x<=cx+rx;x++){const d=((x-cx)/rx)**2+((y-cy)/ry)**2+(n2(x/6,y/4)-.5)*.4;if(d<1&&x>=0&&x<SW){const up=(cy-y)/ry;put(x,y,up>.55?K3.i9:up>.1?(bay(x,y)<.6?K3.i8:K3.i7):K3.i6)}}};
  mound(6,236,30,14);mound(252,234,26,15);
}
genIce();
const ICER=[K3.i3,K3.g1,K3.g2,K3.g3,K3.g4,K3.i9];
function drawIce(T,camx,camy,beat){copyBG(iceBuf,camx,camy);
  const put=(x,y,c)=>{const X=x+camx,Y=y+camy;if(X>=0&&Y>=0&&X<SW&&Y<SH)buf[Y*SW+X]=c};
  const H=ice.hole;for(let k=0;k<H.length;k+=3){const x=H[k+1],y=H[k+2];let a=0;
    for(let q=0;q<2;q++){const yc=26+q*10+7*Math.sin(x*.03+T*.4+q*2.1)+3*Math.sin(x*.09-T*.6+q);const d=y-yc;const band=d>0?Math.exp(-((d/2.2)**2)):Math.exp(d/10);
      const rays=.5+.3*Math.sin(x*1.1+T*2.4+q*5+3*Math.sin(x*.07+T*.3))+.2*Math.sin(x*2.7-T*3.1);a=Math.max(a,band*rays*(.7+.3*Math.sin(x*.05-T*.5+q)))}
    if(a>.22&&bay(x,y)<a*1.1){put(x,y,a>.72?K3.a2:a>.42?K3.a1:K3.a3)}}
  const Cr=ice.crys;for(let k=0;k<Cr.length;k+=5){const x=Cr[k+1],y=Cr[k+2],t=Cr[k+3],f=Cr[k+4];
    if(f===4){const v=.5+.5*beat+st.bgE*.2;put(x,y,v>.9?K3.i9:v>.6?K3.g4:K3.g3);continue}
    const v=Math.sin(t*.28-T*2.2+x*.13);if(v>.93)put(x,y,K3.i9);else if(v>.8&&f>=1)put(x,y,K3.i8)}
  const G=ice.glow,gl=.26+.32*beat+st.energy*.08;for(let k=0;k<G.length;k+=4){const x=G[k+1],y=G[k+2],d=G[k+3];if(bay(x,y)<gl*(1-d)*1.2)put(x,y,d<.35?K3.g3:d<.7?K3.g2:K3.g1)}
  const Kc=ice.crack,rig=FORMS[fi].rig;for(let k=0;k<Kc.length;k+=4){const x=Kc[k+1],y=Kc[k+2],d=Kc[k+3];
    const v=.2+.25*Math.sin(d*.22-T*2.6)+.5*beatAt(rig,T-d/70)*Math.max(0,1-d/110)+st.bgE*.35-d/260;put(x,y,ICER[clamp(Math.floor(v*5+bay(x,y)),0,5)])}
  const Gl=ice.glint;for(let k=0;k<Gl.length;k+=3){const x=Gl[k+1],y=Gl[k+2];if(Math.sin(T*3+x*1.7+y)>.85)put(x,y,K3.i9)}
}

// ---------- forest biome (Sève) ----------
const FORH={f0:'050d12',f1:'08161c',f2:'0c2128',f3:'123036',f4:'1a4246',f5:'245a58',f6:'317466',m0:'0f2a1c',m1:'1d4a2c',m2:'2a6a34',m3:'3f8c3c',m4:'67b84a',m5:'9ad86a',
  g1:'1e5e4a',g2:'2f9c6e',g3:'5ee8a0',g4:'c8ffd8',r1:'16343a',r2:'21494e',p1:'c04aa8',p2:'ff8ad8',y1:'e8ff7a',y2:'fff9c8',b1:'1a1418',b2:'2a2024',b3:'3a2e30',b4:'4e3c3a',c1:'3fe0d0',c2:'a8fff4',c0:'1c6a66'};
const K4={};for(const k in FORH)K4[k]=hex2u32(FORH[k]);
const forBuf=new Uint32Array(SW*SH),forA={ray:[],crack:[],glow:[],mush:[],vines:[],ferns:[],grass:[]};
function genForest(){const B=forBuf,Rf=mulberry(4242);
  const put=(x,y,c)=>{x=Math.round(x);y=Math.round(y);if(x>=0&&y>=0&&x<SW&&y<SH)B[y*SW+x]=c};
  const ramp=[K4.f0,K4.f1,K4.f2,K4.f3,K4.f4,K4.f5];
  for(let y=0;y<SH;y++)for(let x=0;x<SW;x++){const v=clamp(.08+.62*Math.exp(-(((y-150)/70)**2))+.12*(n2(x/22,y/16)-.5),0,1);const k=v*(ramp.length-1),i=Math.floor(k);B[y*SW+x]=ramp[clamp(i+((k-i)>bay(x,y)?1:0),0,5)]}
  // far, mid and near trunks
  const trunk=(cx,w,col,edge,top)=>{for(let y=top;y<186;y++){const ww=w+(y>160?(y-160)*.25:0);for(let x=Math.round(cx-ww/2);x<=Math.round(cx+ww/2);x++){let c=col;if(x===Math.round(cx+ww/2))c=edge;if(n2(x/2,y/9)>.7)c=edge;put(x,y,c)}}};
  for(let i=0;i<9;i++)trunk(14+i*29+Rf()*10,4+Rf()*3,K4.f4,K4.f5,0);
  for(let i=0;i<5;i++)trunk(8+i*60+Rf()*20,9+Rf()*5,K4.f2,K4.f3,0);
  trunk(10,26,K4.f1,K4.f2,0);trunk(246,30,K4.f1,K4.f2,0);trunk(36,12,K4.f1,K4.f2,0);
  // canopy with gaps of light
  for(let y=0;y<46;y++)for(let x=0;x<SW;x++){const v=n2(x/14,y/9)+.35*n2(x/5,y/4)-y/80;if(v>.62)put(x,y,v>.85?K4.f0:K4.m0);else if(v>.5&&bay(x,y)<.5)put(x,y,K4.m0);else if(v<.2&&y<30)put(x,y,v<.12?K4.f6:K4.f5)}
  // god rays
  for(const[x0,w]of[[70,16],[132,22],[188,12]])for(let y=10;y<200;y++){const cx=x0+(y-10)*.45;for(let x=Math.round(cx-w/2);x<=Math.round(cx+w/2);x++){if(x<0||x>=SW)continue;const e=1-Math.abs(x-cx)/(w/2),a=e*(1-y/220)*.55;if(bay(x,y)<a)forA.ray.push(y*SW+x,x,y,e)}}
  // hanging vines (drawn animated)
  for(let i=0;i<9;i++)forA.vines.push([12+Rf()*232,Rf()*10,30+Rf()*70,Rf()*6.28]);
  // mossy floor
  const top=x=>Math.round(176+3*n1(x/16,7));
  for(let y=168;y<SH;y++)for(let x=0;x<SW;x++){if(y<top(x))continue;const d=y-top(x);let v=.5+.3*(n2(x/7,y/4)-.5)+.25*(n2(x/2.5,y/2)-.5)-d*.006;
    let c=v>.68?K4.m3:v>.5?K4.m2:v>.34?K4.m1:K4.m0;if(d===0)c=K4.m4;else if(d<3&&bay(x,y)<.5)c=K4.m3;B[y*SW+x]=c;
    const gd=Math.hypot((x-CX)/76,(y-GY+1)/13);if(gd<1)forA.glow.push(y*SW+x,x,y,gd)}
  // roots crossing the floor (some glow near the creature)
  for(let r=0;r<9;r++){let x=Rf()*SW,y=180+Rf()*50,a=(Rf()-.5)*.8;const L=40+Rf()*70;for(let i=0;i<L;i++){const X=Math.round(x),Y=Math.round(y);put(X,Y,K4.b3);put(X,Y+1,K4.b1);put(X,Y-1,K4.b4);
      const dc=Math.hypot(X-CX,(Y-GY)*3);if(dc<110)forA.crack.push(Y*SW+X,X,Y,dc);x+=Math.cos(a);y+=Math.sin(a)*.5;a+=(Rf()-.5)*.25}}
  // stones, flowers and glowing mushrooms
  for(let i=0;i<10;i++){const x=Rf()*SW,y=186+Rf()*46;for(let dy=-2;dy<=1;dy++)for(let dx=-3;dx<=3;dx++)if(dx*dx/9+dy*dy/4<1)put(x+dx,y+dy,dy<0?K4.f6:K4.f4)}
  for(let i=0;i<26;i++){const x=Rf()*SW,y=182+Rf()*50;put(x,y,K4.p2);put(x+1,y,K4.p1);put(x,y+1,K4.m3)}
  const mush=(x,y,s)=>{for(let k=0;k<s;k++)put(x,y-k,K4.y2);for(let dx=-s;dx<=s;dx++){const h=Math.round((1-(dx/s)**2)*s*.7);for(let k=0;k<=h;k++)forA.mush.push((y-s-k)*SW+Math.round(x+dx),Math.round(x+dx),y-s-k,k/(h+.001))}};
  [[24,196,3],[30,199,2],[20,201,2],[228,192,3],[236,197,2],[221,199,2],[66,186,2],[190,186,2],[178,206,2]].forEach(a=>mush(...a));
  // front ferns and grass (animated)
  for(const[bx,dir]of[[-4,1],[14,1],[260,-1],[242,-1]])for(let f=0;f<6;f++)forA.ferns.push([bx,244,dir*(.35+f*.22+Rf()*.1),26+Rf()*20,Rf()*6.28]);
  for(let x=0;x<SW;x+=2)forA.grass.push([x+Rf(),9+Rf()*9+(Math.abs(x-128)<40?4:0),(Rf()-.5)*4,Rf()*6.28]);
}
genForest();
function drawForest(T,camx,camy,beat){copyBG(forBuf,camx,camy);
  const put=(x,y,c)=>{x=Math.round(x+camx);y=Math.round(y+camy);if(x>=0&&y>=0&&x<SW&&y<SH)buf[y*SW+x]=c};
  const Ry=forA.ray;for(let k=0;k<Ry.length;k+=4){const x=Ry[k+1],y=Ry[k+2],e=Ry[k+3];const v=.5+.5*Math.sin(T*.6+x*.03-y*.02);put(x,y,e>.6&&v>.55?K4.r2:K4.r1)}
  for(const[vx,vy,L,ph]of forA.vines){for(let i=0;i<L;i++){const sw=Math.sin(T*.9+ph+i*.06)*i*.05;const x=vx+sw,y=vy+i;put(x,y,K4.m1);if(i%7===3){put(x-1,y,K4.m2);put(x+1,y+1,K4.m3)}}}
  const Gw=forA.glow,gl=.24+.32*beat+st.energy*.08;for(let k=0;k<Gw.length;k+=4){const x=Gw[k+1],y=Gw[k+2],d=Gw[k+3];if(bay(x,y)<gl*(1-d)*1.2)put(x,y,d<.35?K4.g2:K4.g1)}
  const Kc=forA.crack,rig=FORMS[fi].rig;for(let k=0;k<Kc.length;k+=4){const x=Kc[k+1],y=Kc[k+2],d=Kc[k+3];
    const v=.15+.25*Math.sin(d*.22-T*2.6)+.5*beatAt(rig,T-d/70)*Math.max(0,1-d/110)+st.bgE*.4-d/240;if(v>.45)put(x,y,v>.85?K4.g4:v>.65?K4.g3:K4.g2)}
  const M=forA.mush;for(let k=0;k<M.length;k+=4){const x=M[k+1],y=M[k+2],q=M[k+3];const v=.5+.5*Math.sin(T*1.6+x*.4);put(x,y,q>.6?(v>.5?K4.c2:K4.c1):(v>.3?K4.c1:K4.c0))}
}
function drawForestFront(T,camx,camy){const put=(x,y,c)=>{x=Math.round(x+camx);y=Math.round(y+camy);if(x>=0&&y>=0&&x<SW&&y<SH)buf[y*SW+x]=c};
  const wind=Math.sin(T*.8)*1.5+Math.sin(T*1.9)*.6;
  for(const[x,h,lean,ph]of forA.grass){for(let i=0;i<h;i++){const t=i/h,sx=x+(lean+wind+Math.sin(T*2.2+ph)*.8)*t*t;put(sx,SH-1-i,t>.8?K4.m4:t>.4?K4.m3:K4.m2)}}
  for(const[bx,by,a,L,ph]of forA.ferns){const sw=Math.sin(T*1.1+ph)*.06;for(let i=0;i<L;i++){const t=i/L,ang=-Math.PI/2+(a+sw)*(.3+t*1.2);const x=bx+Math.cos(ang)*i*1.05,y=by+Math.sin(ang)*i*1.05+t*t*8;
      put(x,y,K4.m2);if(i%2===0&&i>3){const ll=Math.round(5*(1-t)+1);for(let j=1;j<=ll;j++){put(x+Math.cos(ang-1.2)*j,y+Math.sin(ang-1.2)*j,j>ll-2?K4.m4:K4.m3);put(x+Math.cos(ang+1.2)*j,y+Math.sin(ang+1.2)*j,K4.m3)}}}}
}
