const img=octx.createImageData(SW,SH),buf=new Uint32Array(img.data.buffer);
let fi=0,ci=0; // current form and creature
const st={dim:0,act:null,blinkUntil:0,nextBlink:1.5,dbl:0,energy:0,shake:0,flash:0,pokeT:-9,nextAuto:6,evo:null,extraFires:[],bgE:0};
let P=[];          // particles
